[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\usetikzlibrary{calc}
\coordinate (O) at (0,0);
\coordinate (Ap) at (0,2.8);
\coordinate (Lp) at (-2.1,0);
\coordinate (Rp) at (2.1,0);
\draw (Lp) arc (180:360:2.1 and 0.672);
\draw[dashed] (Rp) arc (0:180:2.1 and 0.672);
\draw (Ap) -- (Rp) node[midway,right] {$l$};
\draw (Ap) -- (Lp);
\draw[dashed] (Ap) -- (O) node[midway,left] {$h$};
\draw (O) -- (Rp) node[midway,below] {$r$};
\coordinate (ra) at ($(O)!0.28cm!(Ap)$);
\coordinate (rb) at ($(O)!0.28cm!(Rp)$);
\draw (ra) -- ($(ra)+(rb)-(O)$) -- (rb);
\fill (O) circle (1.2pt);
\end{tikzpicture}
[/tikz]

